// Read-only snapshot of what is actually IN the CRM right now.
// The question this answers: can we WRITE THE EMAILS? So it checks, for every
// send-ready lead, whether every merge field its assigned template consumes is
// actually populated. Field lists come from COLD_EMAIL_PLAYBOOK.md.
// Maps every column BY HEADER NAME so a reordered sheet cannot misread it.
try {
  var res = $input.first().json;
  var values = (res && res.values) || [];
  if (values.length < 2) { return [{ json: { error: 'Sheet read returned no rows', raw: res } }]; }

  var headers = values[0];
  var idx = {};
  for (var h = 0; h < headers.length; h++) { idx[String(headers[h]).trim()] = h; }

  function cell(row, name) {
    var i = idx[name];
    if (i === undefined) { return ''; }
    var v = row[i];
    return (v === undefined || v === null) ? '' : String(v).trim();
  }
  function isTrue(v) {
    var s = String(v).toLowerCase();
    return s === 'true' || s === 'yes' || s === '1';
  }
  function bump(o, k) {
    var key = (k === '' || k === undefined) ? '(blank)' : k;
    o[key] = (o[key] || 0) + 1;
  }

  // Merge fields each template actually consumes (COLD_EMAIL_PLAYBOOK.md).
  // First Name is deliberately EXCLUDED - the playbook defines a 'Hi,' fallback,
  // so a missing first name never blocks a send.
  var REQ1 = {
    'A':      ['Top Competitor','Competitor Reviews','Review Count','Top Complaint'],
    'A-v2':   ['Top Competitor','Competitor Reviews','Review Count','Best Review Quote'],
    'A-lite': ['Top Competitor','Competitor Reviews','Review Count'],
    'B':      ['Top Complaint'],
    'D':      ['Company Name','City','Trade','Trade Scene']
  };
  var REQ2 = {
    'E1': ['Closing Time'],
    'E2': ['Top Competitor','Competitor Reviews'],
    'E3': []
  };

  var rows = values.slice(1);
  var total = rows.length;

  var byRoute = {}, byPriority = {}, byStatus = {}, byCountry = {},
      bySizeTier = {}, byTrade = {}, byEntity = {}, byEmail2 = {};

  var enriched = { googleMatched: 0, hasCallPrep: 0, hasComplaint: 0,
                   hasQuote: 0, hasFirstName: 0, hasCompetitor: 0,
                   hasOpeningHours: 0, hasClosingTime: 0, hasWebsite: 0 };

  var sendable = 0, blockedPecr = 0, blockedNotEmailable = 0,
      blockedNoEmail = 0, alreadySent = 0;

  var readyByRoute = {};
  var t1 = {}, t2 = {};   // per-template completeness among send-ready leads

  function track(store, route, row, reqMap) {
    if (!store[route]) { store[route] = { assigned: 0, complete: 0, incomplete: 0, missingField: {} }; }
    var s = store[route];
    s.assigned++;
    var req = reqMap[route];
    if (!req) { s.unknownRoute = true; return; }
    var ok = true;
    for (var q = 0; q < req.length; q++) {
      if (cell(row, req[q]) === '') {
        ok = false;
        s.missingField[req[q]] = (s.missingField[req[q]] || 0) + 1;
      }
    }
    if (ok) { s.complete++; } else { s.incomplete++; }
  }

  for (var r = 0; r < total; r++) {
    var row = rows[r];

    var route = cell(row, 'Template Route');
    var route2 = cell(row, 'Email 2 Route');
    bump(byRoute, route);
    bump(byEmail2, route2);
    bump(byPriority, cell(row, 'Priority'));
    bump(byStatus, cell(row, 'Status'));
    bump(byCountry, cell(row, 'UK Country'));
    bump(bySizeTier, cell(row, 'Size Tier'));
    bump(byTrade, cell(row, 'Trade'));
    bump(byEntity, cell(row, 'Entity Type'));

    if (cell(row, 'Google Rating') !== '') { enriched.googleMatched++; }
    if (cell(row, 'Call Prep Card') !== '') { enriched.hasCallPrep++; }
    if (cell(row, 'Top Complaint') !== '') { enriched.hasComplaint++; }
    if (cell(row, 'Best Review Quote') !== '') { enriched.hasQuote++; }
    if (cell(row, 'First Name') !== '') { enriched.hasFirstName++; }
    if (cell(row, 'Top Competitor') !== '') { enriched.hasCompetitor++; }
    if (cell(row, 'Opening Hours') !== '') { enriched.hasOpeningHours++; }
    if (cell(row, 'Closing Time') !== '') { enriched.hasClosingTime++; }
    if (cell(row, 'Website') !== '') { enriched.hasWebsite++; }

    var email = cell(row, 'Email');
    var emailable = isTrue(cell(row, 'Emailable'));
    var pecr = isTrue(cell(row, 'PECR Risk'));
    var sent = cell(row, 'Email Sent');

    if (sent !== '') { alreadySent++; }
    else if (email === '') { blockedNoEmail++; }
    else if (pecr) { blockedPecr++; }
    else if (!emailable) { blockedNotEmailable++; }
    else {
      sendable++;
      bump(readyByRoute, route);
      track(t1, route, row, REQ1);
      track(t2, route2, row, REQ2);
    }
  }

  var personalised = (readyByRoute['A'] || 0) + (readyByRoute['A-v2'] || 0) +
                     (readyByRoute['B'] || 0);

  var writable = 0;
  var routeKeys = Object.keys(t1);
  for (var z = 0; z < routeKeys.length; z++) { writable += t1[routeKeys[z]].complete; }

  return [{ json: {
    generatedAt: new Date().toISOString(),
    totalRows: total,
    headerCount: headers.length,

    sendReady: {
      sendableNow: sendable,
      personalisedReady: personalised,
      byRoute: readyByRoute
    },

    // THE ANSWER: how many send-ready leads have every merge field their
    // assigned template needs.
    emailsWritableNow: writable,
    email1Readiness: t1,
    email2Readiness: t2,

    blocked: {
      alreadyEmailed: alreadySent,
      noEmail: blockedNoEmail,
      pecrRisk: blockedPecr,
      notEmailable: blockedNotEmailable
    },

    enrichmentCoverage: enriched,
    byTemplateRoute: byRoute,
    byEmail2Route: byEmail2,
    byPriority: byPriority,
    byStatus: byStatus,
    byUkCountry: byCountry,
    bySizeTier: bySizeTier,
    byTrade: byTrade,
    byEntityType: byEntity
  }}];
} catch (e) {
  return [{ json: { error: 'CRM Status failed: ' + e.message } }];
}
